/** A reset-authorizing import marker cannot survive an acknowledged successful import. */
@Isolated
class LmdbInitialRunImportTerminalCleanupTest {

	private static final int ROWS = 130;

	@TempDir
	Path directory;

	@ParameterizedTest
	@EnumSource(CleanupSite.class)
	@Timeout(60)
	void terminalCleanupFailureCannotAcknowledgeDataThatRestartWillReset(CleanupSite site) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setBulkOperationSize(64);
		Path marker = directory.resolve(LmdbInitialRunImport.MARKER_FILE_NAME);
		Path target = site == CleanupSite.RUN_DIRECTORY
				? directory.resolve(LmdbInitialRunImport.RUN_DIRECTORY_NAME)
				: marker;
		IOException injected = new IOException("injected terminal import cleanup failure: " + site);
		LmdbStore sail = new LmdbStore(directory.toFile(), config);
		sail.init();
		Throwable commitFailure;
		Throwable peerFailure;
		long completed;
		long peerRows;
		TerminalObservation observation = new TerminalObservation();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			ValueStore values = backing.valueStore();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				var vf = SimpleValueFactory.getInstance();
				for (int row = 0; row < ROWS; row++) {
					writer.addStatement(vf.createIRI("urn:terminal-cleanup:subject:" + row),
							vf.createIRI("urn:terminal-cleanup:predicate"), vf.createLiteral("value " + row));
				}
				assertThat(backing.isInitialRunImportActive()).isTrue();
				assertThat(marker).exists();
				long tripleCommitsBefore = triples.getNativeCommitGeneration();
				long valueCommitsBefore = values.nativeCommitGeneration();
				Thread writerThread = Thread.currentThread();
				try (MockedStatic<Files> ignored = mockStatic(Files.class, call -> {
					if (call.getMethod().getName().equals("deleteIfExists")
							&& ((Path) call.getArgument(0)).toAbsolutePath().equals(target.toAbsolutePath())) {
						observation.calls++;
						observation.thread = Thread.currentThread();
						observation.tripleCommits = triples.getNativeCommitGeneration() - tripleCommitsBefore;
						observation.valueCommits = values.nativeCommitGeneration() - valueCommitsBefore;
						observation.activeTripleWriter = triples.writeTxn;
						// Cleanup runs inside import ownership. A managed reader could reacquire that barrier;
						// an independent native snapshot proves the rows actually committed before the fault.
						observation.committedRows = LmdbUtil.readTransaction(triples.env,
								(stack, txn) -> LmdbPersistentAdjacency.openExisting(txn).count(txn, true));
						if (site != CleanupSite.SUCCESS) {
							observation.injected++;
							throw injected;
						}
					}
					return call.callRealMethod();
				})) {
					commitFailure = catchThrowable(writer::commit);
				}
				assertThat(observation.thread).as("observe the actual caller's terminal cleanup")
						.isSameAs(writerThread);
				completed = backing.initialRunImportsCompleted();
				AtomicLong visible = new AtomicLong(-1L);
				peerFailure = catchThrowable(() -> {
					try (LmdbStoreConnection peer = (LmdbStoreConnection) sail.getConnection()) {
						visible.set(peer.size());
					}
				});
				peerRows = visible.get();
				assertThat(backing.isInitialRunImportActive()).as("terminal ownership is released").isFalse();
				assertThat(Files.exists(marker)).isEqualTo(site != CleanupSite.SUCCESS);
			}
		} finally {
			sail.shutDown();
		}

		long reopenedRows;
		LmdbStore reopened = new LmdbStore(directory.toFile(), config);
		reopened.init();
		try (LmdbStoreConnection reader = (LmdbStoreConnection) reopened.getConnection()) {
			reopenedRows = reader.size();
		} finally {
			reopened.shutDown();
		}
		System.out.printf("terminal-import-cleanup site=%s calls=%d injected=%d tripleCommits=%d valueCommits=%d "
				+ "committedRowsBeforeFault=%d commitAcknowledged=%s completed=%d peerRows=%d reopenedRows=%d%n",
				site, observation.calls, observation.injected, observation.tripleCommits, observation.valueCommits,
				observation.committedRows, commitFailure == null, completed, peerRows, reopenedRows);
		assertAll("terminal cleanup must not acknowledge data that the surviving marker authorizes resetting",
				() -> assertThat(observation.calls).isEqualTo(1),
				() -> assertThat(observation.tripleCommits).isPositive(),
				() -> assertThat(observation.valueCommits).isPositive(),
				() -> assertThat(observation.activeTripleWriter).isZero(),
				() -> assertThat(observation.committedRows).isEqualTo(ROWS),
				() -> assertThat(marker).doesNotExist(),
				() -> {
					if (site == CleanupSite.SUCCESS) {
						assertThat(observation.injected).isZero();
						assertThat(commitFailure).isNull();
						assertThat(peerFailure).isNull();
						assertThat(completed).isEqualTo(1);
						assertThat(peerRows).isEqualTo(ROWS);
						assertThat(reopenedRows).isEqualTo(ROWS);
					} else {
						assertThat(observation.injected).isEqualTo(1);
						assertThat(commitFailure).isInstanceOf(SailException.class);
						assertThat(containsIdentity(commitFailure, injected)).isTrue();
						assertThat(completed).as("failed cleanup cannot report a completed import").isZero();
						assertThat(peerFailure).isInstanceOf(SailException.class);
						assertThat(containsIdentity(peerFailure, injected)).isTrue();
						assertThat(peerRows).as("the live store fails closed until restart").isEqualTo(-1L);
						// This is the existing interrupted, UNACKNOWLEDGED initial-import recovery contract.
						assertThat(reopenedRows).isZero();
					}
				});
	}

	private static boolean containsIdentity(Throwable failure, Throwable expected) {
		Set<Throwable> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		return containsIdentity(failure, expected, visited);
	}

	private static boolean containsIdentity(Throwable failure, Throwable expected, Set<Throwable> visited) {
		if (failure == null || !visited.add(failure)) {
			return false;
		}
		if (failure == expected || containsIdentity(failure.getCause(), expected, visited)) {
			return true;
		}
		for (Throwable suppressed : failure.getSuppressed()) {
			if (containsIdentity(suppressed, expected, visited)) {
				return true;
			}
		}
		return false;
	}

	private enum CleanupSite {
		SUCCESS,
		RUN_DIRECTORY,
		MARKER
	}

	private static final class TerminalObservation {
		private int calls;
		private int injected;
		private Thread thread;
		private long tripleCommits;
		private long valueCommits;
		private long activeTripleWriter;
		private long committedRows;
	}
}
